from collections import deque,Counter
def components(A,bg_set=None):
    R,C=len(A),len(A[0])
    if bg_set is None:
        cnt=Counter(v for r_ in A for v in r_); bg=set(d for d,_ in cnt.most_common(1)[:2])
    else: bg=bg_set
    seen=[[False]*C for _ in range(R)]; out=[]
    for r in range(R):
        for c in range(C):
            if not seen[r][c] and A[r][c] not in bg:
                q=deque([(r,c)]);seen[r][c]=True;cells=[]
                while q:
                    a,b=q.popleft();cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<R and 0<=y<C and not seen[x][y] and A[x][y] not in bg:
                            seen[x][y]=True;q.append((x,y))
                out.append(cells)
    return out

def f_fill(A):
    R,C=len(A),len(A[0])
    cnt=Counter(v for r_ in A for v in r_)
    bg=cnt.most_common(1)[0][0]  # dominant = background? careful
    # try: bg = most common; others are noise.
    O=[row[:] for row in A]
    seen=[[False]*C for _ in range(R)]
    for r in range(R):
        for c in range(C):
            if not seen[r][c] and A[r][c]!=bg:
                q=deque([(r,c)]);seen[r][c]=True;cells=[]
                while q:
                    a,b=q.popleft();cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<R and 0<=y<C and not seen[x][y] and A[x][y]==A[a][b] or False: 
                            seen[x][y]=True;q.append((x,y))
                # same-component noise set
                nd={int(A[a][b]) for a,b in cells}
                d=min(nd)
                for a,b in cells:
                    if A[a][b]==bg: O[a][b]=d+5
    return O

